const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const games=[{id:'wheel',name:'LE888 SPIN',sub:'Spin · Win · Multiply',asset:'spin',cost:1},{id:'plinko',name:'ORANGE DROP',sub:'Drop · Bounce · Win',asset:'drop',cost:2},{id:'scratch',name:'LE888 FLIP',sub:'Pick · Flip · Win',asset:'flip',cost:12},{id:'egg',name:'LUCKY VAULT',sub:'Choose · Unlock · Win',asset:'vault',cost:5},{id:'cross',name:'LUCKY CROSSING',sub:'Cross · Survive · Win',asset:'cross',cost:5},{id:'crown',name:'CROWN PICK',sub:'Pick · Flip · Win',asset:'crownpick',cost:10}];
const state={page:'home',game:0,bet:10,claimed:false,rewardTab:'Daily',historyTab:'All',busy:false,sound:true,notifications:true};
const screen=document.querySelector('#screen'),header=document.querySelector('#header'),nav=document.querySelector('#bottom-nav'),modal=document.querySelector('#modal');
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200)}
function go(page){if(state.busy){clearTimeout(state.previewTimer);state.busy=false}state.page=page;location.hash=page;render();window.scrollTo(0,0)}
const button=(label,to,cls='')=>`<button class="${cls}" data-go="${to}">${label}</button>`;
const member=(profile=false)=>`<div class="member panel"><div class="avatar">${icon('user')}</div><div>${profile?'':'<small>Welcome Back</small>'}<b>${memberName()}</b>${profile?'<small>ID: '+memberID()+'</small>':''}</div><span class="vip-badge">${icon('crown')} MEMBER</span><button class="chev" data-go="${profile?'account':'profile'}" aria-label="View profile">›</button></div>`;
const balance=()=>`<div class="balance panel">${icon('wallet')}<div><small>Available Points</small><strong>${memberPoints()} PTS</strong></div><button class="plus" data-go="deposit" aria-label="Add points">+</button></div>`;
const section=(title,to,label='See All')=>`<div class="section-heading"><h2>${title}</h2>${to?button(label+' ›',to,'text-link'):''}</div>`;
const tile=g=>`<button class="game-tile" data-game="${g.id}"><img src="assets/${g.asset}.png" alt="${g.name} artwork"><span class="tile-title"><b>${g.name}</b><small>${g.sub}</small></span></button>`;
function home(){return member()+`<div class="banner"><h2>SMALL GAMES<br><strong>BIG REWARDS</strong></h2><p>PLAY ANYTIME, WIN ALWAYS</p>${button('PLAY NOW &nbsp; →','games','gold-btn')}</div>`+balance()+`<div class="action-strip panel">${[['deposit','Deposit','deposit'],['withdraw','Withdraw','withdraw'],['gift','Rewards','rewards'],['crown','VIP','vip']].map(([i,l,p])=>button(icon(i)+l,p)).join('')}</div>`+section('Explore Games','games')+`<div class="game-grid">${games.slice(0,2).map(tile).join('')}</div><div class="daily-teaser panel">${icon('calendar')}<div><b>Your daily rewards are waiting</b><small>Build your streak. Make every day count.</small></div>${button('›','rewards','chev')}</div>`+section('Quick Actions','actions','View All')+`<div class="secondary-actions">${[['crown','VIP Club','vip'],['gift','Promotions','promotions'],['calendar','Check In','rewards'],['rtp','RTP Info','rtp']].map(([i,l,p])=>button(icon(i)+l,p)).join('')}</div>`}
function deck(){return `<div class="deck-intro"><div class="deck-points" aria-label="Available Points: ${memberPoints()} PTS"><div><small>✦ AVAILABLE POINTS</small><strong>${memberPoints()} <span>PTS</span></strong></div><button class="deck-points-add" data-go="deposit" aria-label="Deposit to top up points">+</button></div><p>CHOOSE YOUR GAME</p></div><div class="deck-stage" tabindex="0" aria-label="Swipe or use arrow keys to explore games">${games.map((g,i)=>`<button class="deck-card${g.soon?' soon':''}" data-deck="${i}" aria-label="${g.name}"><img src="assets/${g.asset}.png" alt="">${g.soon?'<span class="soon-badge">SOON</span>':''}<span class="tile-title"><b>${g.name}</b><small>${g.sub.toUpperCase()}</small></span></button>`).join('')}</div><div class="deck-dots">${games.map((g,i)=>`<button data-select="${i}" aria-label="Select ${g.name}"></button>`).join('')}</div><div class="deck-controller panel"><button class="deck-arrow" data-step="-1" aria-label="Previous game">❮</button><div><p>Swipe to Explore</p><small>Tap to Play</small></div><button class="deck-arrow" data-step="1" aria-label="Next game">❯</button></div><button class="play-orb" id="deck-play">PLAY</button><p class="play-note">Explore all our games. Your next lucky move awaits.</p>`}
function actions(){return section('Quick Actions')+`<div class="action-pair">${button(icon('deposit')+'<b>Deposit</b><small>Fast & Secure</small>','deposit','action-large')}${button(icon('withdraw')+'<b>Withdraw</b><small>Review your balance</small>','withdraw','action-large blue')}</div><div class="secondary-actions">${[['crown','VIP Club','Exclusive','vip'],['gift','Promotions','Hot Events','promotions'],['calendar','Check In','Daily Bonus','rewards'],['rtp','RTP Info','Game Data','rtp']].map(([i,l,s,p])=>button(icon(i)+l+`<small>${s}</small>`,p)).join('')}</div><div class="banner vip-banner"><h2>VIP CLUB</h2><p>HIGHER TIER<br>BIGGER REWARDS</p>${button('EXPLORE &nbsp; →','vip','gold-btn')}</div>`+section('Latest Promotions','promotions')+`<div class="banner promo-banner"><h2>DAILY CHECK-IN<br><strong>BONUS</strong></h2><p>YOUR DAILY REWARDS, ALL IN ONE PLACE</p>${button('VIEW REWARDS →','rewards','gold-btn')}</div>`}
const missions=[['games','Play 5 games',3,5,20],['spark','Win 3 times',1,3,15],['wallet','Deposit today',0,1,50],['people','Invite a friend',0,1,100]];
function missionRows(){return missions.map(([i,t,n,max,pts])=>`<div class="mission panel">${icon(i)}<div class="mission-copy"><p>${t}<small>${n}/${max}</small></p><div class="progress"><i style="width:${n/max*100}%"></i></div></div><span class="pill">+ ${pts} PTS</span></div>`).join('')}
function rewards(){let content='';if(state.rewardTab==='Daily')content=`<div class="reward-card"><h2>DAILY CHECK-IN</h2><p>7 Days Streak Rewards</p><div class="days">${[1,2,3,4,5].map(d=>`<div class="day ${d===3?'today':''}">${icon(d<3||(d===3&&state.claimed)?'check':d===3?'gift':'lock')}<small>Day ${d}</small></div>`).join('')}</div><button class="primary-btn" id="claim" ${state.claimed?'disabled':''}>${state.claimed?'Today claimed ✓':'Claim Today + 5 PTS'}</button></div>`+section('Daily Missions','missions')+'<p class="subtitle">Complete missions to earn more points</p>'+missionRows();if(state.rewardTab==='Missions')content=section('Daily Missions')+missionRows();if(state.rewardTab==='Weekly')content=`<div class="reward-card"><h2>YOUR WEEKLY REWARDS</h2><p>Keep playing to unlock the next milestone.</p><div class="stats"><div><b>3 / 7</b><small>Active days</small></div><div><b>12</b><small>Games played</small></div><div><b>25 PTS</b><small>Next reward</small></div></div><div class="progress"><i style="width:43%"></i></div>${button('View VIP benefits','vip','primary-btn')}</div>`;if(state.rewardTab==='VIP')content=vip();return `<div class="tabs">${['Daily','Weekly','Missions','VIP'].map(t=>`<button data-reward-tab="${t}" class="${state.rewardTab===t?'active':''}">${t}</button>`).join('')}</div>`+content}
const profileLinks=[['wallet','My Wallet','wallet'],['history','Transaction History','history'],['gift','My Rewards','rewards'],['crown','VIP Club','vip'],['people','Invite Friends','invite'],['settings','Settings','settings'],['help','Help & Support','support']];
const menuList=links=>`<div class="menu-list panel">${links.map(([i,t,p])=>button(icon(i)+t+'<span class="chev">›</span>',p)).join('')}</div>`;
function profile(){return member(true)+balance()+`<div class="stats panel"><div><b>3</b><small>Days Streak</small></div><div><b>12</b><small>Games Played</small></div><div><b>5</b><small>Total Wins</small></div></div>`+menuList(profileLinks)}
const vipRanks = [
  {name:'Member', key:'member', deposit:500, color:'#e9c977'},
  {name:'Silver', key:'silver', deposit:1500, color:'#cfd6e0'},
  {name:'Gold', key:'gold', deposit:3000, color:'#ffd274'},
  {name:'Platinum', key:'platinum', deposit:6000, color:'#dfe7ef'},
  {name:'Diamond', key:'diamond', deposit:12000, color:'#bfe6ff'},
  {name:'Royal', key:'royal', deposit:25000, color:'#ff6a6a'},
  {name:'Legend', key:'legend', deposit:50000, color:'#ffb447'}
];
/* Ranks come from the server when signed in (names, thresholds, bonuses); the list above is the offline fallback. */
function vipList(){try{const v=window.memberData&&memberData.vip;if(v&&Array.isArray(v.ranks)&&v.ranks.length)return v.ranks.map((r,i)=>({name:r.name,key:r.key||(vipRanks[i]||vipRanks[0]).key,deposit:Number(r.deposit)||0,color:(vipRanks[i]||vipRanks[0]).color,weekly:r.weekly,upgrade:r.upgrade}));}catch(e){}return vipRanks;}
function vipBadge(r,dim){return `<span class="rank-emblem${dim?' dim':''}" style="--rank-color:${r.color}" aria-hidden="true"><img src="/assets/vip-${r.key}.webp" alt=""></span>`;}
function vip(){
  const tab=state.vipTab||'all';
  const list=vipList();
  const rank=list[2]; // preview only; the signed-in app shows the real rank (member-session)
  const badge=vipBadge;
  return `<div class="vip-ranks"><div class="vip-switch" role="group" aria-label="VIP ranks"><button data-vip-tab="my" aria-pressed="${tab==='my'}" class="${tab==='my'?'active':''}">My Rank</button><button data-vip-tab="all" aria-pressed="${tab==='all'}" class="${tab==='all'?'active':''}">All Ranks</button></div>${tab==='all'?`<div class="vip-rank-list">${list.map((r,i)=>`<article class="vip-rank-row">${badge(r)}<div class="vip-rank-info"><h2>${r.name}</h2><p>Deposit $${r.deposit.toLocaleString('en-US')}</p></div><button class="vip-view" data-vip-detail="${i}" aria-label="View ${r.name} rank details">View more <span aria-hidden="true">›</span></button></article>`).join('')}</div>`:`<section class="my-rank-panel panel">${badge(rank)}<span class="vip-demo-label">YOUR RANK · DEMO</span><h2>${rank.name}</h2><p>MEMBER · Deposit $${rank.deposit.toLocaleString('en-US')}</p><div class="vip-next"><span>Next rank</span><b>${list[3].name}</b><small>Deposit $${list[3].deposit.toLocaleString('en-US')}</small></div><button class="vip-view" data-vip-tab="all">Explore All Ranks <span aria-hidden="true">›</span></button></section>`}</div>`;
}
document.addEventListener('click',e=>{
 const tab=e.target.closest('[data-vip-tab]');
 if(tab){state.vipTab=tab.dataset.vipTab;render();return;}
 const detail=e.target.closest('[data-vip-detail]');
 if(detail){const r=vipList()[Number(detail.dataset.vipDetail)];if(!r)return;modal.className='vip-detail-modal';const perks=(r.weekly!==undefined||r.upgrade!==undefined)?`<div class="vip-perks">${r.weekly!==undefined?`<div><b>${Number(r.weekly).toLocaleString('en-US')} PTS</b><small>Weekly bonus</small></div>`:''}${r.upgrade!==undefined?`<div><b>${Number(r.upgrade).toLocaleString('en-US')} PTS</b><small>Upgrade bonus</small></div>`:''}</div>`:'<div class="notice">Rank benefits are shown once you sign in.</div>';showModal(r.name,`<div class="vip-detail-emblem rank-emblem" style="--rank-color:${r.color}"><img src="/assets/vip-${r.key}.webp" alt=""></div><p class="vip-detail-threshold">Deposit <strong>$${r.deposit.toLocaleString('en-US')}</strong></p><p class="subtitle">This month's deposit total to reach ${r.name}</p>${perks}`);}
});
function transactions(){const rows=[['gift','Daily check-in','Today · 09:41','+ 5 PTS'],['games','LE888 SPIN','Yesterday · 18:32','− 10 PTS'],['wallet','Reward credit','Yesterday · 18:32','+ SGD 2.50']];return `<p class="subtitle">Sample activity shown for the local preview.</p><div class="tabs">${['All','Points','Rewards'].map(t=>`<button data-history-tab="${t}" class="${t===state.historyTab?'active':''}">${t}</button>`).join('')}</div><div class="panel">${rows.filter(r=>state.historyTab==='All'||(state.historyTab==='Points'?r[3].includes('PTS'):r[3].includes('SGD'))).map(([i,t,d,a])=>`<div class="record">${icon(i)}<div><b>${t}</b><small>${d}</small></div><strong>${a}</strong></div>`).join('')}</div>`}
function money(type){const dep=type==='deposit';return `<p class="subtitle">${dep?'Top up your account and get back to the games.':'Choose your balance and review your withdrawal.'}</p><form id="money-form" class="form-panel panel">${!dep?'<label for="source">Withdraw from</label><select id="source"><option>Reward Credits · SGD 0.00</option><option>Game Balance · SGD 0.00</option></select>':''}<label for="amount">Amount (SGD)</label><input id="amount" name="amount" type="number" min="1" step="0.01" placeholder="0.00" required><div class="amounts">${[10,50,100,500].map(n=>`<button type="button" data-amount="${n}">${n}</button>`).join('')}</div><label for="method">${dep?'Payment method':'Payout method'}</label><select id="method"><option>Bank Transfer</option><option>PayNow</option></select>${!dep?'<label for="bank">Bank / PayNow account</label><input id="bank" required placeholder="Enter account details" autocomplete="off">':''}<button class="primary-btn" type="submit">Review ${dep?'Deposit':'Withdrawal'} →</button></form><div class="notice">Local preview: this form does not submit payments or store bank details. Real account services require the original backend.</div>`}
function wallet(){return balance()+`<div class="panel" style="padding:18px;margin-top:12px"><small style="color:var(--muted)">Reward Credits</small><h2 style="color:var(--gold);margin-top:7px">SGD 0.00</h2>${button('Submit Rewards →','submit','primary-btn')}</div><div class="action-pair" style="margin-top:15px">${button(icon('deposit')+'<b>Deposit</b>','deposit','action-large')}${button(icon('withdraw')+'<b>Withdraw</b>','withdraw','action-large blue')}</div>`+menuList([['history','Transaction History','history']])}
function settings(){return `<div class="panel"><div class="toggle-row"><span>Sound Effects</span><button class="toggle ${state.sound?'on':''}" data-toggle="sound" aria-label="Sound effects" aria-pressed="${state.sound}"></button></div><div class="toggle-row"><span>Notifications</span><button class="toggle ${state.notifications?'on':''}" data-toggle="notifications" aria-label="Notifications" aria-pressed="${state.notifications}"></button></div></div><div class="form-panel panel" style="margin-top:13px"><label for="language">Language</label><select id="language"><option>English</option><option>简体中文</option></select></div>`+menuList([['user','Account Details','account'],['lock','Change Password','password'],['help','Terms & Conditions','terms']])+`<button class="primary-btn" id="signout">Sign Out</button>`}
function account(){return `<form class="form-panel panel" id="account-form"><label for="name">Display Name</label><input id="name" value="Player001" required><label for="player-id">Player ID</label><input id="player-id" value="928374" readonly><label for="phone">Phone Number</label><input id="phone" type="tel" placeholder="Add phone number"><button class="primary-btn">Save Details</button></form>`}
function password(){return `<form class="form-panel panel" id="password-form"><label for="old-pass">Current Password</label><input id="old-pass" type="password" required autocomplete="current-password"><label for="new-pass">New Password</label><input id="new-pass" type="password" minlength="8" required autocomplete="new-password"><button class="primary-btn">Update Password</button></form>`}
function invite(){return `<div class="rank-card panel">${icon('people')}<h2>PLAY TOGETHER</h2><p>Invite your friends to the LE888 arcade.</p></div><div class="form-panel panel" style="margin-top:15px"><label for="invite-code">Your referral code</label><input id="invite-code" value="LE888-PLAYER001" readonly><button class="primary-btn" id="copy-invite">Copy Code</button></div><div class="notice">Referral rewards and eligibility are confirmed by the original backend.</div>`}
function support(){return `<p class="subtitle">We're here to help with your account, rewards and games.</p>`+menuList([['chat','Live Chat','chat'],['deposit','Deposit & Withdrawal Help','payment-help'],['gift','Reward Help','reward-help']])+`<div class="notice">This local preview does not connect to live support.</div>`}
function chat(){return `<div id="chat-messages"><div class="chat-message"><b>LE888 Support</b><br>Welcome! How can we help you today?</div></div><form id="chat-form" class="chat-input"><input aria-label="Message" placeholder="Type a message…" required><button aria-label="Send message">${icon('chat')}</button></form><p class="play-note">Preview chat · messages stay in this page only.</p>`}
function rtp(){return `<p class="subtitle">Explore game information and recent performance.</p><div class="rtp-grid">${games.filter(g=>!g.soon).map(g=>`<div class="rtp-card panel"><b>${g.name}</b><strong>—</strong><small>Live RTP requires backend data</small><button class="primary-btn" data-game="${g.id}">View Game</button></div>`).join('')}</div>`}
function promotions(){return `<div class="banner promo-banner"><h2>DAILY CHECK-IN<br><strong>BONUS</strong></h2><p>RETURN DAILY · BUILD YOUR STREAK</p>${button('VIEW REWARDS →','rewards','gold-btn')}</div><div class="banner vip-banner"><h2>VIP EXCLUSIVES</h2><p>DISCOVER YOUR MEMBER BENEFITS</p>${button('VIEW VIP CLUB →','vip','gold-btn')}</div>`+menuList([['gift','Deposit Bonus','deposit-bonus'],['calendar','Daily Missions','missions']])}
function gamePage(){const g=games[state.game];if(g.id==='cross')return crossPage();if(g.id==='crown')return crownPage();if(g.soon)return `<div class="form-panel panel soon-panel"><div class="soon-art"><img src="assets/soon.png" alt=""></div><h2>Coming soon</h2><p class="subtitle" style="margin-top:12px">A brand-new LE888 game is on the way. Stay tuned!</p>${button('Back to games','games','primary-btn')}</div>`;const jackpots='';let game='';if(g.id==='wheel'){game=wheelMarkup();}else if(g.id==='plinko'){const pc=plinkoConf();let labels=pc&&pc.prizes.length?pc.prizes.slice(0,10):['x2','x3','x5','x10','x5','x3','x2'];const art=labels.length<=7;const off=art?Math.floor((7-labels.length)/2):0;const pockets=art?Array.from({length:7},(_,j)=>{const i=j-off;return(i>=0&&i<labels.length)?plinkoLabel(labels[i]):null;}):labels.map(plinkoLabel);game=`<div class="plinko-board${art?'':' custom-pockets'}" data-pockets="${pockets.length}" data-offset="${off}"><div class="plinko-pegs"></div><img class="plinko-ball-img" id="ball" src="/assets/drop-ball.webp" alt="">${art?'':'<div class="plinko-pockets">'+labels.map(()=>'<i></i>').join('')+'</div>'}<div class="plinko-slots">${pockets.map((x,j)=>'<span class="pslot'+(x===null?' off':'')+'" data-slot="'+j+'">'+(x===null?'':x)+'</span>').join('')}</div></div>`;}else if(g.id==='scratch')game=`<div class="flip-table"><div class="flip-grid">${[0,1,2,3,4,5,6,7,8].map(i=>`<button class="flip-card" data-flip="${i}" aria-label="Card ${i+1}"><span class="flip-inner"><span class="flip-face flip-back"><img src="/assets/flip-back.webp" alt=""></span><span class="flip-face flip-front"><img src="/assets/flip-front.webp" alt=""><b class="flip-prize"></b></span></span></button>`).join('')}</div></div>`;else game=`<div class="game-grid vault-grid" style="margin-top:20px">${[0,1,2,3].map(i=>`<button class="game-tile vault-tile" data-vault="${i}"><img src="assets/vault.png" alt="Vault ${i+1}"><span class="vault-prize"><small>YOU WON</small><b></b></span><span class="tile-title"><b>VAULT 0${i+1}</b></span></button>`).join('')}</div>`;const live=gameConf(g.id);if(live){const ok=live.enabled&&live.prizes.length>=1;const verb={plinko:'DROP',scratch:'FLIP',wheel:'SPIN',egg:'PICK'}[g.id]||'PLAY';const btn={plinko:'DROP',scratch:'TAP A CARD',wheel:'SPIN',egg:'TAP A VAULT'}[g.id]||'PLAY';return jackpots+game+`<div class="bet-control plinko-cost"><span id="bet-label">${live.cost} PTS PER ${verb}</span></div><button class="spin-btn" id="game-start" ${ok?'':'disabled'}>${btn}<small>${ok?('COSTS '+live.cost+' PTS'):'NOT AVAILABLE'}</small></button><p class="play-note">Prizes are reward credits (SGD) and are decided by the server.</p>`;}return jackpots+game+`<div class="bet-control"><button data-bet="-10" aria-label="Decrease points">−</button><span id="bet-label">${state.bet} PTS</span><button data-bet="10" aria-label="Increase points">+</button></div><div class="amounts">${[10,50,100,500].map(n=>`<button data-stake="${n}" class="${state.bet===n?'active':''}">${n}</button>`).join('')}</div><button class="spin-btn" id="game-start">${g.id==='wheel'?'SPIN':g.id==='plinko'?'DROP':g.id==='scratch'?'CHOOSE A CARD':'CHOOSE A VAULT'}<small>PREVIEW ANIMATION</small></button><p class="play-note">Demo visuals only · no points deducted and no prize outcome.</p>`}
const titles={actions:'Quick Actions',rewards:'Rewards',profile:'Profile',deposit:'Deposit',withdraw:'Withdraw',vip:'VIP Club',history:'Transaction History',wallet:'My Wallet',settings:'Settings',account:'Account Details',password:'Change Password',invite:'Invite Friends',support:'Help & Support',chat:'Live Chat',rtp:'RTP Info',promotions:'Promotions',missions:'Daily Missions',submit:'Submit Rewards','deposit-bonus':'Deposit Bonus',terms:'Terms & Conditions','payment-help':'Payment Help','reward-help':'Reward Help',platforms:'Game Platforms'};
function render(){const page=state.page,root=['home','games','rewards','profile'].includes(page);header.innerHTML=page==='home'?button(icon('menu'),'menu','icon-btn')+'<img class="brand-img" src="/assets/logo888.webp" alt="LE888">'+button(icon('chat')+'<span class="chat-dot"></span>','chat','icon-btn'):page==='games'?button(icon('back'),'home','icon-btn')+'<span class="back-label">THE ARCADE</span>'+button(icon('chat'),'chat','icon-btn'):button(icon(root?'menu':'back'),root?'menu':page==='game'?'games':'profile','icon-btn')+`<span class="${page==='game'?'game-header':'page-title'}">${page==='game'?games[state.game].name:titles[page]||'LE888'}</span>`+button(icon(page==='profile'?'settings':'chat'),page==='profile'?'settings':'chat','icon-btn');let content='';const routes={home, games:deck, actions,rewards,profile,vip,history:transactions,deposit:()=>money('deposit'),withdraw:()=>money('withdraw'),wallet,settings,account,password,invite,support,chat,rtp,promotions,missions:missionRows,game:gamePage,platforms:()=>platformsPage(),submit:()=>`<div class="form-panel panel"><small>Available Reward Credits</small><h2 style="color:var(--gold);margin-top:10px">SGD 0.00</h2><p class="subtitle" style="margin-top:15px">Choose a linked game account to submit your credits.</p><label for="platform">Game Platform</label><select id="platform"><option>Select your linked account</option></select><button class="primary-btn" id="submit-preview">Review Submission</button></div><div class="notice">Account links and eligibility require the original backend.</div>`,'deposit-bonus':()=>`<div class="rank-card panel">${icon('gift')}<h2>DEPOSIT BONUS</h2><p>Your next reward starts here.</p></div><div class="notice">Current tiers, eligibility and terms are loaded from the original backend. No live offers are available in this preview.</div>${button('View Deposit','deposit','primary-btn')}`,terms:()=>`<div class="form-panel panel"><h2>Terms & Conditions</h2><p class="subtitle" style="margin-top:15px">The original service terms must be loaded from the backend before publishing. This page shows the new reading layout.</p></div>`,'payment-help':()=>`<div class="form-panel panel"><h2>Account payments</h2><p class="subtitle" style="margin-top:14px">Use Deposit to choose a payment method, or Withdraw to review an available balance. For account-specific help, contact support.</p>${button('Live Chat','chat','primary-btn')}</div>`,'reward-help':()=>`<div class="form-panel panel"><h2>Rewards & check-in</h2><p class="subtitle" style="margin-top:14px">Visit Rewards to view your daily streak, missions and VIP benefits. Live eligibility and claiming are handled by the original service.</p>${button('View Rewards','rewards','primary-btn')}</div>`};content=(routes[page]||home)();screen.className=page==='games'?'deck-page screen-enter':'screen-enter';screen.innerHTML=content;document.body.classList.toggle('game-lock',page==='game'&&!games[state.game].soon);const active=page==='game'?'games':['missions','promotions'].includes(page)?'rewards':['home','actions'].includes(page)?'home':root?page:'profile';bind();if(page==='games')updateDeck();if(page==='game')scheduleFit()}
function updateDeck(){document.querySelectorAll('.deck-card').forEach((c,i)=>{const n=games.length;let d=(i-state.game+n)%n;if(d>n/2)d-=n;c.style.setProperty('--d',d);c.style.setProperty('--s',d===0?1:.78);c.style.setProperty('--o',Math.abs(d)>1?0:d===0?1:.7);c.style.setProperty('--z',10-Math.abs(d));c.classList.toggle('selected',d===0);c.style.pointerEvents=Math.abs(d)>1?'none':'auto';c.setAttribute('aria-current',d===0?'true':'false')});document.querySelectorAll('[data-select]').forEach((b,i)=>b.classList.toggle('active',i===state.game))}
function select(n){const c=games.length;state.game=(n+c)%c;updateDeck()}
function showModal(title,body){modal.innerHTML=`<h2>${title}</h2>${body}<button class="primary-btn" id="modal-close">Close</button>`;modal.querySelector('#modal-close').onclick=()=>modal.close();modal.showModal()}
function menu(){showModal('LE888',`<div class="menu-drawer">${[['home','Home','home'],['games','Games','games'],['wallet','Action Center','actions'],['gift','Rewards','rewards'],['crown','VIP Club','vip'],['rtp','RTP Info','rtp'],['games','Game Platforms','platforms'],['user','Profile','profile'],['help','Help & Support','support']].map(([i,t,p])=>button(icon(i)+t,p)).join('')}</div>`);modal.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{modal.close();go(b.dataset.go)})}
/* Orange Drop config comes from the admin prize table (Admin -> Games -> Plinko) via /api/member/me. */
function gameConf(id){if(id!=='plinko'&&id!=='scratch'&&id!=='cross'&&id!=='crown'&&id!=='wheel'&&id!=='egg')return null;try{const g=(typeof memberGame==='function')?memberGame(id):null;if(!g||!Array.isArray(g.prizes))return null;return{cost:Number(g.cost)||0,prizes:g.prizes.map(String),enabled:!!g.enabled};}catch(e){return null;}}
function flipNudge(){document.querySelectorAll('.flip-card:not(.flipped)').forEach((c,i)=>{c.classList.remove('nudge');void c.offsetWidth;c.style.animationDelay=(i*60)+'ms';c.classList.add('nudge');});}
function flipLabel(v){const t=plinkoLabel(v);if(/^x/i.test(t))return '<span>'+t+'</span>';if(t==='0')return '<small>NO</small><span>WIN</span>';return '<small>SGD</small><span>'+t+'</span>';}
function flipReveal(card,label,tier,demo){if(!card)return;const p=card.querySelector('.flip-prize');if(p)p.innerHTML=flipLabel(label);card.classList.add('flipped');card.classList.toggle('win',tier>0);card.classList.toggle('lose',tier===0);if(demo){document.querySelectorAll('.flip-card').forEach(o=>{if(o!==card)o.classList.add('dim');});setTimeout(flipResetAll,1900);}}
function flipResetAll(){document.querySelectorAll('.flip-card').forEach(c=>{c.classList.remove('flipped','win','lose','dim','picked');});setTimeout(()=>{document.querySelectorAll('.flip-prize').forEach(p=>{p.innerHTML='';});},700);}
async function flipPlay(card){if(state.busy||!card||card.classList.contains('flipped'))return;const pc=gameConf('scratch');if(!pc||!pc.enabled){toast('LE888 Flip is not available right now.');return;}if(!pc.prizes.length){toast('LE888 Flip has no prizes set yet.');return;}state.busy=true;const start=document.querySelector('#game-start');if(start)start.disabled=true;const cards=[...document.querySelectorAll('.flip-card')];card.classList.add('picked');cards.forEach(o=>{if(o!==card)o.classList.add('dim');});
 let res;try{res=await memberRequest('play',{game:'scratch',play_id:plinkoPlayId()});}catch(e){state.busy=false;if(start)start.disabled=false;cards.forEach(o=>o.classList.remove('dim','picked'));toast(e&&e.message?e.message:'Could not play. Please try again.');return;}
 try{if(res&&typeof res.points==='number')memberData.member.points=res.points;if(res&&res.reward!==undefined)memberData.member.reward=res.reward;}catch(e){}
 const cents=Number(res.win_cents)||Math.round(Number(res.win)*100)||0;let maxC=0;pc.prizes.forEach(p=>{const c=Math.round(Number(p)*100);if(c>maxC)maxC=c;});const tier=cents<=0?0:(cents>=maxC&&maxC>0?2:1);
 flipReveal(card,String(res.win),tier,false);
 setTimeout(()=>{if(tier>0)plinkoWin(tier,document.querySelector('.flip-table'));try{if(navigator.vibrate)navigator.vibrate(tier>=2?[50,40,70]:(tier?30:15));}catch(e){}toast(cents>0?('You won SGD '+plinkoLabel(res.win)+' reward credit!'):'No prize this time. Try again!');},650);
 /* the other cards show what they held (visual only) */
 setTimeout(()=>{const others=cards.filter(o=>o!==card);others.forEach((o,i)=>{setTimeout(()=>{const pick=pc.prizes[Math.floor(Math.random()*pc.prizes.length)];const p=o.querySelector('.flip-prize');if(p)p.innerHTML=flipLabel(pick);o.classList.add('flipped','lose');},i*90);});},1300);
 setTimeout(()=>{flipResetAll();state.busy=false;if(start)start.disabled=false;},tier>0?3600:3000);}
/* ===== CROWN PICK — pick tiles until 3 of a kind. The SERVER picks the winning tier; the app only deals the reveals. ===== */
const CROWN_TIERS=[{key:'grand',name:'GRAND',color:'#ff5a5a'},{key:'major',name:'MAJOR',color:'#4f9bff'},{key:'minor',name:'MINOR',color:'#c07cff'},{key:'mini',name:'MINI',color:'#3fd48a'}];
const crown={round:false,busy:false,seq:[],pos:0,counts:{},tiers:[],winTier:-1,over:true,demo:null};
function crownConf(){const pc=gameConf('crown');if(pc)return{cost:pc.cost,prizes:pc.prizes.slice(0,5),enabled:pc.enabled,live:true};return{cost:10,prizes:['77.77','50.77','30.77','10.77','0.00'],enabled:true,live:false};}
/* tiers = paying prizes sorted high->low (GRAND, MAJOR, MINOR, MINI) + an optional NO WIN tier for a 0.00 prize */
function crownTiers(c){const pay=c.prizes.map((p,i)=>({p:String(p),v:Number(p)||0,i})).filter(x=>x.v>0).sort((a,b)=>b.v-a.v).slice(0,4);const tiers=pay.map((x,k)=>Object.assign({},CROWN_TIERS[k],{prize:x.p,value:x.v}));const dud=c.prizes.find(p=>!(Number(p)>0));if(dud!==undefined)tiers.push({key:'dud',name:'NO WIN',color:'#8a8a8a',prize:String(dud),value:0});return tiers;}
function crownPage(){const c=crownConf();const tiers=crownTiers(c);const ok=c.enabled&&tiers.length>=1;return `<div class="crown-wrap"><img class="crown-title" src="/assets/crown-title.webp" alt="Crown Pick"><div class="crown-jackpots">${tiers.filter(t=>t.key!=='dud').map(t=>'<div class="crown-jp" data-tier="'+t.key+'" style="--c:'+t.color+'"><img src="/assets/crown-'+t.key+'.webp" alt=""><b>'+t.name+'</b><strong>'+plinkoLabel(t.prize)+'</strong></div>').join('')}</div><div class="crown-grid" id="crown-grid">${Array.from({length:16}).map((_,i)=>'<button class="crown-tile" data-tile="'+i+'" aria-label="Tile '+(i+1)+'"><span class="crown-inner"><span class="crown-face crown-back"><img src="/assets/crown-back.webp" alt=""></span><span class="crown-face crown-front"><img src="/assets/crown-back.webp" alt=""></span></span></button>').join('')}</div><div class="crown-status" id="crown-status"><b>${ok?('Tap any tile to begin · '+c.cost+' PTS'):'Not available'}</b><small>${c.live?'Match 3 of a kind to win that jackpot · wins go to Reward Credits':'Demo · no PTS used'}</small></div><button class="spin-btn crown-again" id="crown-again" hidden>PLAY AGAIN<small>COSTS ${c.cost} PTS</small></button><p class="play-note">${c.live?'The winning jackpot is decided by the server before your first pick.':'Demo visuals only · no points deducted and no prize outcome.'}</p></div>`;}
function crownInit(){crown.round=false;crown.busy=false;crown.over=true;crown.seq=[];crown.pos=0;crown.counts={};crown.winTier=-1;document.querySelectorAll('.crown-tile').forEach(t=>{t.onclick=()=>crownTap(t);});const again=document.querySelector('#crown-again');if(again)again.onclick=()=>{crownReset();};}
function crownShuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));const t=a[i];a[i]=a[j];a[j]=t;}return a;}
/* deal order: the winner shows 3 times, its 3rd between the 5th and 9th reveal; every other tier at most twice */
function crownSequence(win,n){const others=[];for(let t=0;t<n;t++)if(t!==win)others.push(t,t);crownShuffle(others);const want=Math.min(others.length,2+Math.floor(Math.random()*5));const decoys=others.slice(0,want);const total=decoys.length+3;const seq=new Array(total).fill(null);seq[total-1]=win;const slots=crownShuffle(Array.from({length:total-1},(_,i)=>i));seq[slots[0]]=win;seq[slots[1]]=win;let d=0;for(let i=0;i<total-1;i++)if(seq[i]===null)seq[i]=decoys[d++];return seq;}
function crownDemoPlay(tiers){const w=tiers.map(t=>t.key==='dud'?45:t.key==='grand'?2:t.key==='major'?6:t.key==='minor'?15:32);let tot=0;w.forEach(x=>tot+=x);let r=Math.random()*tot,idx=tiers.length-1;for(let i=0;i<w.length;i++){if(r<w[i]){idx=i;break;}r-=w[i];}const t=tiers[idx];return Promise.resolve({ok:true,win:t.prize,win_cents:Math.round(t.value*100)});}
function crownStatus(html,sub){const st=document.querySelector('#crown-status');if(!st)return;st.innerHTML='<b>'+html+'</b>'+(sub?'<small>'+sub+'</small>':'');}
async function crownTap(tile){if(crown.busy||tile.classList.contains('flipped'))return;const c=crownConf();const tiers=crownTiers(c);if(!c.enabled||!tiers.length){toast('Crown Pick is not available right now.');return;}
 if(!crown.round){crown.busy=true;let res;try{res=c.live?await memberRequest('play',{game:'crown',play_id:plinkoPlayId()}):await crownDemoPlay(tiers);}catch(e){crown.busy=false;toast(e&&e.message?e.message:'Could not start. Please try again.');return;}
  crossBalances(res);let win=tiers.findIndex(t=>t.prize===String(res.win));if(win<0)win=tiers.findIndex(t=>Math.abs(t.value-Number(res.win))<0.005);if(win<0)win=tiers.length-1;
  crown.round=true;crown.over=false;state.busy=true;crown.winTier=win;crown.seq=crownSequence(win,tiers.length);crown.pos=0;crown.counts={};crown.busy=false;crownStatus('Keep picking…','Match 3 of a kind to win that jackpot');}
 const t=tiers[crown.seq[crown.pos++]];crown.counts[t.key]=(crown.counts[t.key]||0)+1;
 const img=tile.querySelector('.crown-front img');img.src='/assets/crown-'+t.key+'.webp';tile.dataset.tier=t.key;tile.style.setProperty('--c',t.color);tile.classList.add('flipped');try{if(navigator.vibrate)navigator.vibrate(15);}catch(e){}
 const jp=document.querySelector('.crown-jp[data-tier="'+t.key+'"]');if(jp){jp.classList.remove('tick');void jp.offsetWidth;jp.classList.add('tick');jp.querySelector('b').textContent=t.name+' '+'●'.repeat(crown.counts[t.key]);}
 if(crown.counts[t.key]>=3){crown.busy=true;setTimeout(()=>crownWin(t,tiers),520);return;}
 crownStatus(t.name+' × '+crown.counts[t.key],'Two more of the same and it\'s yours');}
function crownWin(t,tiers){const grid=document.querySelector('#crown-grid');crown.over=true;crown.round=false;state.busy=false;
 document.querySelectorAll('.crown-tile').forEach(x=>{if(x.dataset.tier===t.key)x.classList.add('win');else x.classList.add('dim');});
 const jp=document.querySelector('.crown-jp[data-tier="'+t.key+'"]');document.querySelectorAll('.crown-jp').forEach(j=>j.classList.add('fade'));if(jp){jp.classList.remove('fade');jp.classList.add('won');}
 const rank=tiers.findIndex(x=>x.key===t.key);
 if(t.key==='dud'){crownStatus('No win this time','Three cracked tiles — try again!');toast('No prize this time. Try again!');try{if(navigator.vibrate)navigator.vibrate([30,30,30]);}catch(e){}}
 else{const big=t.key==='grand';crownStatus(t.name+' JACKPOT · SGD '+plinkoLabel(t.prize),'Added to your Reward Credits');toast('You won the '+t.name+' jackpot — SGD '+plinkoLabel(t.prize)+'!');if(grid){crossConfetti(grid,big?90:(rank<=1?50:25));plinkoWin(big?2:1,grid);if(big)crossFireworks(grid);const fl=document.createElement('div');fl.className='cross-flash'+(big?' big':'');grid.appendChild(fl);setTimeout(()=>fl.remove(),950);}try{if(navigator.vibrate)navigator.vibrate(big?[60,40,60,40,120]:[50,40,80]);}catch(e){}}
 const again=document.querySelector('#crown-again');if(again){again.hidden=false;again.disabled=true;setTimeout(()=>{again.disabled=false;crown.busy=false;},t.key==='dud'?900:(t.key==='grand'?3200:2000));}}
function crownReset(){const again=document.querySelector('#crown-again');if(again)again.hidden=true;document.querySelectorAll('.crown-tile').forEach(x=>{x.classList.remove('flipped','win','dim');x.removeAttribute('data-tier');});document.querySelectorAll('.crown-jp').forEach(j=>{j.classList.remove('won','fade','tick');const n=j.dataset.tier;const tt=CROWN_TIERS.find(z=>z.key===n);if(tt)j.querySelector('b').textContent=tt.name;});setTimeout(()=>{document.querySelectorAll('.crown-front img').forEach(i=>{i.src='/assets/crown-back.webp';});},600);const c=crownConf();crownInit();crownStatus('Tap any tile to begin · '+c.cost+' PTS','Match 3 of a kind to win that jackpot');}
