function crossPage(){const c=crossConf();const n=c.prizes.length;const ok=c.enabled&&n>=1;return `<div class="cross-wrap"><div class="cross-board" id="cross-board"><img class="cross-road" src="/assets/cross-road.webp" alt="" draggable="false"><div class="cross-cars" id="cross-cars"></div><div class="cross-barriers" id="cross-barriers"></div><div class="cross-badges">${c.prizes.map((p,i)=>'<div class="cross-badge" data-lane="'+(i+1)+'" style="top:'+CROSS_LANE_Y[i]+'%"><img src="/assets/cross-badge.webp" alt=""><b>'+plinkoLabel(p)+'</b></div>').join('')}</div><img class="cross-chicken" id="cross-chicken" src="/assets/cross-chicken.webp" alt="" draggable="false" style="top:${CROSS_START_Y}%"></div><div class="cross-status"><span>${c.live?('Costs '+c.cost+' PTS per game'):'Demo · no PTS used'}</span><b id="cross-current">Tap START</b></div><div class="cross-actions"><button class="spin-btn cross-go" id="cross-go" ${ok?'':'disabled'}>START<small>${ok?('COSTS '+c.cost+' PTS'):'NOT AVAILABLE'}</small></button><button class="cross-collect" id="cross-collect" disabled>COLLECT<small>cross a lane first</small></button></div><p class="play-note">${c.live?'Prizes are reward credits (SGD). Every lane is decided by the server — collect any time.':'Demo visuals only · no points deducted and no prize outcome.'}</p></div>`;}
