/* collect celebration: tier 1 = lanes 1-2, tier 2 = lanes 3-5, tier 3 = crossed the whole street */
function crossCelebrate(tier,amountStr,lane){const board=crossEl('cross-board');if(!board)return;const W=board.clientWidth,H=board.clientHeight;
 const fl=document.createElement('div');fl.className='cross-flash'+(tier>=3?' big':'');board.appendChild(fl);setTimeout(()=>fl.remove(),950);
 const ch=crossEl('cross-chicken');if(ch){ch.classList.remove('joy');void ch.offsetWidth;ch.classList.add('joy');setTimeout(()=>ch.classList.remove('joy'),1300);}
 const badge=board.querySelector('.cross-badge[data-lane="'+lane+'"]');const bx=9.5,by=badge?parseFloat(badge.style.top):50;if(badge){badge.classList.add('cash');setTimeout(()=>badge.classList.remove('cash'),1400);}
 const sparks=tier>=2?22:12;for(let i=0;i<sparks;i++){const sp=document.createElement('i');sp.className='cross-spark';sp.style.left=bx+'%';sp.style.top=by+'%';const a=Math.random()*Math.PI*2,d=W*(0.08+Math.random()*0.16);sp.style.setProperty('--dx',(Math.cos(a)*d).toFixed(1)+'px');sp.style.setProperty('--dy',(Math.sin(a)*d).toFixed(1)+'px');sp.style.animationDelay=(Math.random()*0.18)+'s';board.appendChild(sp);setTimeout(()=>sp.remove(),1400);}
 const fa=document.createElement('div');fa.className='cross-float';fa.textContent='+SGD '+amountStr;fa.style.left=(bx+19)+'%';fa.style.top=by+'%';board.appendChild(fa);setTimeout(()=>fa.remove(),1800);
 plinkoWin(1,board);
 if(tier>=2){const pn=document.createElement('div');pn.className='cross-cashout';const chY=tier>=3?CROSS_END_Y:(CROSS_LANE_Y[lane-1]||50);pn.style.top=(chY<50?'72%':'30%');pn.innerHTML='<div class="cross-rays"></div><div class="cross-ribbon"><small>'+(tier>=3?'STREET CROSSED!':'CASH OUT!')+'</small><b class="cross-amt">SGD 0</b><span>'+(tier>=3?'ALL '+lane+' LANES':'LANE '+lane)+'</span></div>';board.appendChild(pn);
  const target=Number(amountStr)||0,el=pn.querySelector('.cross-amt');let t0=null;const dur=950;(function tick(ts){if(t0===null)t0=ts;const k=Math.min(1,(ts-t0)/dur);const v=target*(1-Math.pow(1-k,3));el.textContent='SGD '+(k<1?v.toFixed(2):plinkoLabel(target.toFixed(2)));if(k<1)requestAnimationFrame(tick);})(performance.now());
  crossConfetti(board,tier>=3?80:45);setTimeout(()=>{pn.classList.add('out');setTimeout(()=>pn.remove(),420);},tier>=3?2700:2100);}
 if(tier>=3){crossFireworks(board);setTimeout(()=>{const bw=document.createElement('img');bw.src='/assets/drop-bigwin.webp';bw.className='plinko-bigwin cross-bigwin';board.appendChild(bw);setTimeout(()=>bw.remove(),2200);},2600);}
 try{if(navigator.vibrate)navigator.vibrate(tier>=3?[60,40,60,40,120]:(tier>=2?[50,40,80]:40));}catch(e){}}
function crossConfetti(board,n){const fall=(board.clientHeight*1.15)+'px';const cols=['#ffd27a','#ff9a2a','#fff0c8','#e9a93f','#ffffff','#ffb347'];for(let i=0;i<n;i++){const c=document.createElement('i');c.className='cross-confetti';c.style.left=(Math.random()*100)+'%';c.style.background=cols[i%cols.length];c.style.setProperty('--fall',fall);c.style.setProperty('--r',(Math.random()*900-450)+'deg');c.style.setProperty('--sx',(Math.random()*60-30)+'px');c.style.animationDuration=(1.7+Math.random()*1.3)+'s';c.style.animationDelay=(Math.random()*0.7)+'s';c.style.width=(5+Math.random()*5)+'px';c.style.height=(8+Math.random()*9)+'px';board.appendChild(c);setTimeout(()=>c.remove(),3400);}}
function crossFireworks(board){for(let i=0;i<5;i++){setTimeout(()=>{const f=document.createElement('i');f.className='cross-firework';f.style.left=(18+Math.random()*64)+'%';f.style.top=(12+Math.random()*50)+'%';f.style.setProperty('--c',['#ffd27a','#ff9a2a','#fff0c8'][i%3]);board.appendChild(f);setTimeout(()=>f.remove(),1300);},i*260);}}
function crossShake(){const b=crossEl('cross-board');if(!b)return;b.classList.remove('shake');void b.offsetWidth;b.classList.add('shake');setTimeout(()=>b.classList.remove('shake'),500);}
function crossSetChicken(y,hit){const ch=crossEl('cross-chicken');if(!ch)return;ch.style.top=y+'%';if(hit){ch.src='/assets/cross-chicken-hit.webp';ch.classList.add('hit');}else{ch.src='/assets/cross-chicken.webp';ch.classList.remove('hit');}}
function crossHop(y){const ch=crossEl('cross-chicken');if(!ch)return;ch.classList.remove('hop');void ch.offsetWidth;ch.classList.add('hop');ch.style.top=y+'%';setTimeout(()=>ch.classList.remove('hop'),480);}
function crossInit(){crossStopTraffic();cross.round=null;cross.lane=0;cross.busy=false;cross.over=true;cross.pending=0;cross.hitLane=-1;cross.cars=[];const go=crossEl('cross-go'),col=crossEl('cross-collect');if(go)go.onclick=crossGo;if(col)col.onclick=crossCollect;cross.traffic=setInterval(crossTick,700);setTimeout(crossTick,150);cross.last=0;cross.raf=requestAnimationFrame(crossLoop);}
function crossStopTraffic(){if(cross.traffic){clearInterval(cross.traffic);cross.traffic=null;}if(cross.raf){cancelAnimationFrame(cross.raf);cross.raf=null;}cross.cars=[];}
/* ===== Traffic engine. Cars are moved by JS (not CSS keyframes) and never stop or vanish. The lane ahead of the chicken is
   always quiet (closed lanes, its own lane and the next two get no traffic), so the hop is instant; on a hit a car comes
   flying in from the edge. The SERVER still decides safe/hit per lane. ===== */
const CROSS_X=50,CROSS_CAR_W=34,CROSS_STOP_GAP=31,CROSS_WIN=26,CROSS_ACC=130;
function crossOccupied(){const o=[];if(cross.lane>0)o.push(cross.lane-1);if(cross.pending>0)o.push(cross.pending-1);return o;}
function crossSpawnCar(laneIdx,dir,dur,opts){const wrap=crossEl('cross-cars');if(!wrap)return null;const car=document.createElement('img');car.src=dir>0?'/assets/cross-car-right.webp':'/assets/cross-car-left.webp';car.className='cross-car';car.style.top=CROSS_LANE_Y[laneIdx]+'%';car.alt='';const x=dir>0?-22:122;car.style.left=x+'%';wrap.appendChild(car);const o={el:car,lane:laneIdx,dir:dir,x:x,vmax:144/dur,v:144/dur,hit:!!(opts&&opts.hit),pass:!!(opts&&opts.hit)};cross.cars.push(o);return o;}
function crossTick(){const wrap=crossEl('cross-cars');if(!wrap){crossStopTraffic();return;}if(cross.cars.length>=5||Math.random()<0.35)return;const n=crossConf().prizes.length;const free=[];const occ=crossOccupied();for(let i=0;i<n;i++){if(i===cross.hitLane||occ.indexOf(i)>=0||i<=cross.lane+1)continue;const dir=i%2?-1:1;const inLane=cross.cars.filter(c=>c.lane===i);if(inLane.length>=2)continue;const edge=dir>0?-22:122;if(inLane.some(c=>Math.abs(c.x-edge)<50))continue;free.push(i);}if(!free.length)return;const li=free[Math.floor(Math.random()*free.length)];crossSpawnCar(li,li%2?-1:1,2.6+Math.random()*1.4);}
function crossStep(dt){const cars=cross.cars;const GAP=CROSS_CAR_W+6;
 for(const c of cars){let vt=c.vmax;
  if(!c.hit){
   /* follow the car ahead: match its speed, never overlap */
   for(const o of cars){if(o===c||o.lane!==c.lane)continue;const d=(o.x-c.x)*c.dir;if(d<=0||d>GAP+40)continue;const f=d>GAP?Math.max(o.v,Math.sqrt(2*CROSS_ACC*(d-GAP))):Math.max(0,o.v-(GAP-d)*4);vt=Math.min(vt,f);}
  }
  if(c.v<vt)c.v=Math.min(vt,c.v+CROSS_ACC*dt);else c.v=Math.max(vt,c.v-CROSS_ACC*1.3*dt);
  c.x+=c.dir*c.v*dt;c.el.style.left=c.x+'%';}
 for(let i=cars.length-1;i>=0;i--){const c=cars[i];if(c.x>125||c.x<-25){c.el.remove();cars.splice(i,1);}}}
function crossLoop(ts){if(!crossEl('cross-cars')){crossStopTraffic();return;}const dt=Math.min(0.05,(ts-(cross.last||ts))/1000);cross.last=ts;crossStep(dt);cross.raf=requestAnimationFrame(crossLoop);}
function crossRoundId(){try{return crypto.randomUUID();}catch(e){return 'c'+Date.now().toString(36)+Math.random().toString(36).slice(2,10);}}
/* local demo server (used only when the real backend config is absent) */
function crossDemoApi(action,body){const lad=['1','2','4','8','16','32'],sv=[85,80,75,70,65,60];const d=cross.demo||(cross.demo={status:'none',lane:0});const st=()=>({ok:true,status:d.status,lane:d.lane,lanes:lad.length,prize:d.lane>0?lad[d.lane-1]:'0.00',win:d.win||'0.00'});
 if(action==='start'){if(d.status!=='active'){d.status='active';d.lane=0;d.win='0.00';d.round=body.round_id;}return Promise.resolve(Object.assign(st(),{round_id:d.round}));}
 if(action==='step'){if(d.status!=='active')return Promise.resolve(st());const next=d.lane+1;if(Math.random()*100<sv[next-1]){d.lane=next;if(next===lad.length){d.status='collected';d.win=lad[next-1];}}else{d.status='hit';d.hit_lane=next;}return Promise.resolve(Object.assign(st(),{hit_lane:d.hit_lane}));}
 if(action==='collect'){if(d.status==='active'&&d.lane>0){d.status='collected';d.win=lad[d.lane-1];}return Promise.resolve(st());}
 return Promise.resolve({ok:false,error:'bad action'});}
function crossApi(action,body){const c=crossConf();if(c.live)return memberRequest('cross/'+action,body);return crossDemoApi(action,body);}
function crossBalances(res){try{if(res&&typeof res.points==='number')memberData.member.points=res.points;if(res&&res.reward!==undefined)memberData.member.reward=res.reward;}catch(e){}}
function crossUi(){const c=crossConf(),go=crossEl('cross-go'),col=crossEl('cross-collect'),cur=crossEl('cross-current');if(!go||!col)return;const n=c.prizes.length;
 if(cross.over){go.innerHTML=(cross.round===null&&cross.lane===0&&!cross.playedOnce?'START':'PLAY AGAIN')+'<small>'+(c.live?('COSTS '+c.cost+' PTS'):'DEMO')+'</small>';go.disabled=!c.enabled||cross.busy;col.disabled=true;col.classList.remove('ready');col.innerHTML='COLLECT<small>cross a lane first</small>';if(cur)cur.textContent=cross.lastMsg||'Tap START';return;}
 go.innerHTML='CROSS<small>'+(cross.lane<n?('TO LANE '+(cross.lane+1)):'FINISH')+'</small>';go.disabled=cross.busy;
 if(cross.lane>0){col.disabled=cross.busy;col.classList.add('ready');col.innerHTML='COLLECT<small>SGD '+plinkoLabel(c.prizes[cross.lane-1])+'</small>';}else{col.disabled=true;col.classList.remove('ready');col.innerHTML='COLLECT<small>cross a lane first</small>';}
 if(cur)cur.textContent=cross.lane>0?('Lane '+cross.lane+' · SGD '+plinkoLabel(c.prizes[cross.lane-1])+' safe'):'On the pavement';}
function crossMarkLanes(){document.querySelectorAll('.cross-badge').forEach(b=>{const k=Number(b.dataset.lane);b.classList.toggle('safe',k<=cross.lane&&cross.lane>0);b.classList.remove('dim');});const wrap=crossEl('cross-barriers');if(!wrap)return;if(cross.lane<=0){wrap.innerHTML='';return;}for(let k=0;k<cross.lane;k++){if(wrap.querySelector('[data-lane="'+k+'"]'))continue;const b=document.createElement('img');b.src='/assets/cross-barrier.webp';b.className='cross-barrier';b.dataset.lane=k;b.style.top=CROSS_LANE_Y[k]+'%';b.style.left=(k%2?90:21)+'%';b.alt='';wrap.appendChild(b);}}
function crossFinishUi(msg){cross.over=true;cross.round=null;cross.playedOnce=true;cross.lastMsg=msg||'';cross.busy=true;crossUi();}
function crossRoundOver(msg){cross.over=true;cross.round=null;cross.playedOnce=true;cross.lastMsg=msg||'';state.busy=false;crossUi();setTimeout(()=>{cross.lane=0;cross.pending=0;cross.hitLane=-1;crossMarkLanes();crossSetChicken(CROSS_START_Y,false);cross.busy=false;crossUi();},1500);}
/* a hit: the lane looked quiet, then a car comes flying in from the edge and crashes into the chicken as it lands */
function crossHitSequence(li,onImpact){const dir=li%2?-1:1;const contact=CROSS_X-dir*11;cross.hitLane=li;const car=crossSpawnCar(li,dir,1.35,{hit:true});if(!car){onImpact();return;}const t=Math.abs(contact-car.x)/car.vmax;setTimeout(onImpact,Math.round(t*1000));}
async function crossGo(){if(cross.busy)return;const c=crossConf();if(!c.enabled){toast('Lucky Crossing is not available right now.');return;}
 if(cross.over){cross.busy=true;crossUi();let res;try{res=await crossApi('start',{round_id:crossRoundId()});}catch(e){cross.busy=false;crossUi();toast(e&&e.message?e.message:'Could not start. Please try again.');return;}
  crossBalances(res);cross.round=res.round_id;cross.over=false;state.busy=true;cross.lane=Number(res.lane)||0;crossSetChicken(cross.lane>0?CROSS_LANE_Y[cross.lane-1]:CROSS_START_Y,false);crossMarkLanes();cross.busy=false;crossUi();toast(res.resumed?'Welcome back — your crossing continues.':'Go! Cross a lane, collect any time.');return;}
  /* step */
 const n=c.prizes.length;const target=cross.lane+1;if(target>n)return;cross.busy=true;cross.pending=target;crossUi();crossHop(CROSS_LANE_Y[target-1]);
 let res;try{res=await crossApi('step',{round_id:cross.round,lane:cross.lane});}catch(e){cross.busy=false;cross.pending=0;crossSetChicken(cross.lane>0?CROSS_LANE_Y[cross.lane-1]:CROSS_START_Y,false);crossUi();toast(e&&e.message?e.message:'Connection problem. Please try again.');return;}
 crossBalances(res);
 if(res.status==='hit'){const hl=(Number(res.hit_lane)||target)-1;crossFinishUi('Hit on lane '+(hl+1));cross.pending=hl+1;crossHitSequence(hl,()=>{crossSetChicken(CROSS_LANE_Y[hl],true);crossShake();try{if(navigator.vibrate)navigator.vibrate([40,30,60]);}catch(e){}toast('Hit by a car! No prize this time.');setTimeout(()=>crossRoundOver('Hit on lane '+(hl+1)),1400);});return;}
 if(res.status==='collected'){cross.lane=Number(res.lane)||target;cross.pending=0;crossMarkLanes();crossFinishUi('Crossed! SGD '+plinkoLabel(res.win));setTimeout(()=>{if(cross.lane>=CROSS_MAX)crossSetChicken(CROSS_END_Y,false);crossCelebrate(3,plinkoLabel(res.win),cross.lane);toast('You crossed the whole street! SGD '+plinkoLabel(res.win)+' collected.');},500);setTimeout(()=>crossRoundOver('Crossed! SGD '+plinkoLabel(res.win)),4200);return;}
 cross.lane=Number(res.lane);cross.pending=0;if(cross.lane!==target)crossSetChicken(cross.lane>0?CROSS_LANE_Y[cross.lane-1]:CROSS_START_Y,false);crossMarkLanes();setTimeout(()=>{cross.busy=false;crossUi();},460);try{if(navigator.vibrate)navigator.vibrate(20);}catch(e){}}
async function crossCollect(){if(cross.busy||cross.over||cross.lane<1)return;cross.busy=true;crossUi();let res;try{res=await crossApi('collect',{round_id:cross.round});}catch(e){cross.busy=false;crossUi();toast(e&&e.message?e.message:'Could not collect. Please try again.');return;}
 crossBalances(res);const c=crossConf();const tier=cross.lane>=c.prizes.length?3:(cross.lane>=3?2:1);crossFinishUi('Collected SGD '+plinkoLabel(res.win));crossCelebrate(tier,plinkoLabel(res.win),cross.lane);toast('Collected SGD '+plinkoLabel(res.win)+' reward credit!');setTimeout(()=>crossRoundOver('Collected SGD '+plinkoLabel(res.win)),tier>=2?1400:300);}
function plinkoConf(){try{const g=(typeof memberGame==='function')?memberGame('plinko'):null;if(!g||!Array.isArray(g.prizes))return null;return{cost:Number(g.cost)||0,prizes:g.prizes.map(String),enabled:!!g.enabled};}catch(e){return null;}}
function plinkoLabel(v){const s=String(v);if(/^x/i.test(s))return s;const n=Number(s);if(!isFinite(n))return s;if(n<=0)return '0';return (Math.round(n*100)%100===0)?String(Math.round(n)):n.toFixed(2);}
function plinkoPlayId(){try{return crypto.randomUUID();}catch(e){return 'p'+Date.now().toString(36)+Math.random().toString(36).slice(2,10);}}
async function plinkoPlay(){if(state.busy)return;const pc=plinkoConf();const start=document.querySelector('#game-start');if(!pc||!pc.enabled){toast('Orange Drop is not available right now.');return;}if(!pc.prizes.length){toast('Orange Drop has no prizes set yet.');return;}state.busy=true;if(start)start.disabled=true;let res;try{res=await memberRequest('play',{game:'plinko',play_id:plinkoPlayId()});}catch(e){state.busy=false;if(start)start.disabled=false;toast(e&&e.message?e.message:'Could not play. Please try again.');return;}
 try{if(res&&typeof res.points==='number')memberData.member.points=res.points;if(res&&res.reward!==undefined)memberData.member.reward=res.reward;}catch(e){}
 let idx=pc.prizes.indexOf(String(res.win));if(idx<0)idx=pc.prizes.findIndex(p=>Number(p)===Number(res.win));if(idx<0)idx=3;
 const cents=Number(res.win_cents)||Math.round(Number(res.win)*100)||0;let maxC=0;pc.prizes.forEach(p=>{const c=Math.round(Number(p)*100);if(c>maxC)maxC=c;});const tier=cents<=0?0:(cents>=maxC&&maxC>0?2:1);
 const boardEl=document.querySelector('.plinko-board');const pocketOff=Number((boardEl&&boardEl.dataset.offset)||0);plinkoDrop(idx+pocketOff,function(){state.busy=false;if(start)start.disabled=false;toast(cents>0?('You won SGD '+plinkoLabel(res.win)+' reward credit!'):'No prize this time. Try again!');},tier);}
function plinkoWallL(W,H,y){return W*0.22+(y-H*0.07)/(H*0.65)*(-W*0.10);}
function plinkoGeom(board){var W=board.clientWidth,H=board.clientHeight;var N=board.querySelectorAll('.pslot').length||7;N=Math.max(1,Math.min(10,N));var R=N-1;var pw=(W*0.76)/N,gap=pw;var rb=Math.min(W*0.025,gap*0.23),rp=Math.min(W*0.011,gap*0.1);var fy0=H*0.17,fy1=H*0.60,rowDy=R>1?(fy1-fy0)/(R-1):0;return{W:W,H:H,N:N,R:R,pw:pw,gap:gap,rb:rb,rp:rp,md:rb+rp,fy0:fy0,fy1:fy1,rowDy:rowDy,px0:W*0.12};}
function plinkoPegs(board){var pegs=board.querySelector('.plinko-pegs');if(!pegs)return[];var g=plinkoGeom(board),W=g.W,H=g.H;pegs.innerHTML='';var co=[];for(var r=0;r<g.R;r++){var ry=g.fy0+g.rowDy*r;var wl=plinkoWallL(W,H,ry)+g.rb*2;var half=W*0.5-wl;var n=(r%2)?2*Math.floor(half/g.gap+0.5):2*Math.floor(half/g.gap)+1;if(n<1)n=0;for(var c=0;c<n;c++){var x=W*0.5+(c-(n-1)/2)*g.gap;if(x<wl||x>W-wl)continue;var el=document.createElement('i');el.style.left=x+'px';el.style.top=ry+'px';el.style.width=el.style.height=Math.max(5,Math.round(g.rp*2))+'px';pegs.appendChild(el);co.push({x:x,y:ry,r:r,el:el});}}return co;}
/* plinkoDrop(target, onDone, tier): target = pocket index. The SERVER decides the pocket; this only animates the ball into it. */
function plinkoDrop(target,onDone,tier){var board=document.querySelector('.plinko-board');if(!board)return;var ball=document.querySelector('#ball');if(!ball)return;var slots=board.querySelectorAll('.pslot');var pegs=plinkoPegs(board);var g=plinkoGeom(board),W=g.W,H=g.H,N=g.N,R=g.R;
if(target===undefined||target===null){var wts=[],i;for(i=0;i<N;i++)wts.push(1+Math.abs(i-(N-1)/2));var tot=0;for(i=0;i<N;i++)tot+=wts[i];var rr=Math.random()*tot;target=N-1;for(i=0;i<N;i++){if(rr<wts[i]){target=i;break;}rr-=wts[i];}}
target=Math.max(0,Math.min(N-1,target|0));var plan=[];for(var q=0;q<target;q++)plan.push(1);for(var q2=0;q2<R-target;q2++)plan.push(-1);for(var m=plan.length-1;m>0;m--){var j=Math.floor(Math.random()*(m+1));var tmp=plan[m];plan[m]=plan[j];plan[j]=tmp;}
var rb=g.rb,md=g.md,gap=g.gap,G=H*4.4;var slotY=H*0.825;var tx=g.px0+g.pw*(target+0.5);
var segs=[],x=W*0.5+(Math.random()*2-1)*W*0.004,y=H*0.05;
function seg(x1,y1,T,vy0,peg){segs.push({x0:x,y0:y,x1:x1,y1:y1,T:T,vy0:vy0,peg:peg||null});x=x1;y=y1;}
function pegAt(r,px){var best=null,bd=1e9;for(var k=0;k<pegs.length;k++){if(pegs[k].r!==r)continue;var d=Math.abs(pegs[k].x-px);if(d<bd){bd=d;best=pegs[k];}}return best;}
var cx=W*0.5;
if(R>0){var c0=g.fy0-md;var T0=Math.sqrt(2*Math.max(1,c0-y)/G);seg(x,c0,T0,0,pegAt(0,x));for(var r=0;r<R;r++){var d=plan[r];cx+=d*gap/2;var jit=(Math.random()*2-1)*W*0.004;if(r<R-1){var ny=g.fy0+g.rowDy*(r+1)-md;var T=0.27+Math.random()*0.06;var vy0=(0.5*G*T*T-(ny-y))/T;seg(cx+jit,ny,T,vy0,pegAt(r+1,cx));}}}
var Tf=R>0?0.3:Math.sqrt(2*(slotY-y)/G);seg(tx,slotY,Tf,R>0?(0.5*G*Tf*Tf-(slotY-y))/Tf:0,null);var Tb=0.17;seg(tx,slotY,Tb,0.5*G*Tb,null);var Tb2=0.1;seg(tx,slotY,Tb2,0.5*G*Tb2,null);
var total=0;for(var si=0;si<segs.length;si++){segs[si].t0=total;total+=segs[si].T;}
ball.style.transition='none';ball.style.opacity='1';ball.style.left=segs[0].x0+'px';ball.style.top=segs[0].y0+'px';ball.style.transform='translate(-50%,-50%)';
var start=0,rot=0,lastX=segs[0].x0,done=false,litIdx=-1;
function settle(){if(done)return;done=true;ball.style.left=tx+'px';ball.style.top=slotY+'px';var slot=slots[target];if(slot){slot.classList.add('hit');setTimeout(function(){slot.classList.remove('hit');},1400);}var tr=(tier===undefined||tier===null||tier<0)?(function(){var m=[2,3,5,10,5,3,2][target]||2;return m>=10?2:(m>=5?1:0);})():tier;if(tr>0)plinkoWin(tr);try{if(navigator.vibrate)navigator.vibrate(tr>=2?[50,40,70]:25);}catch(e){}if(typeof onDone==='function')setTimeout(onDone,tr>0?1500:500);}
function frame(ts){if(done)return;if(!start)start=ts;var t=(ts-start)/1000;if(t>=total){settle();return;}var k=0;while(k<segs.length-1&&t>=segs[k].t0+segs[k].T)k++;var sg=segs[k],tau=t-sg.t0,px=sg.x0+(sg.x1-sg.x0)*(tau/sg.T),py=sg.y0-sg.vy0*tau+0.5*G*tau*tau;rot+=(px-lastX)/rb*30;lastX=px;ball.style.left=px+'px';ball.style.top=py+'px';ball.style.transform='translate(-50%,-50%) rotate('+rot.toFixed(1)+'deg)';
 if(k!==litIdx){litIdx=k;var hit=segs[k>0?k-1:0].peg;if(k>0&&hit&&hit.el){hit.el.classList.add('lit');(function(el){setTimeout(function(){el.classList.remove('lit');},220);})(hit.el);}}
 requestAnimationFrame(frame);}
requestAnimationFrame(frame);}
function plinkoWin(tier,target){var board=target||document.querySelector('.plinko-board');if(!board)return;for(var i=0;i<12;i++){(function(){var c=document.createElement('img');c.src='/assets/drop-coin.webp';c.className='plinko-coin';c.style.left=(10+Math.random()*80)+'%';c.style.width=(7+Math.random()*5)+'%';c.style.animationDelay=(Math.random()*0.35)+'s';board.appendChild(c);setTimeout(function(){c.remove();},1700);})();}if(tier>=2){var bw=document.createElement('img');bw.src='/assets/drop-bigwin.webp';bw.className='plinko-bigwin';board.appendChild(bw);setTimeout(function(){bw.remove();},1900);}}

/* ===== LE888 SPIN (wheel). Segments, cost and chances come from Admin -> Games -> LE888 Spin.
   The SERVER picks the winning prize; the wheel only animates to that segment. ===== */
const WHEEL_DEMO=['x20','x5','x3','x2','x3','x2','x15','x2','x3','x3','x3','x8'];
function wheelConf(){const pc=gameConf('wheel');if(pc)return{cost:pc.cost,prizes:pc.prizes.slice(0,10),enabled:pc.enabled,live:true};return{cost:1,prizes:WHEEL_DEMO,enabled:true,live:false};}
function wheelLabel(v){const s=String(v);if(/^x/i.test(s))return s;const n=Number(s);if(!isFinite(n))return s;if(n<=0)return 'MISS';if(n>=100)return String(Math.round(n));return (Math.round(n*100)%100===0)?String(Math.round(n)):n.toFixed(2);}
function wheelKind(i,N){return (N%2===1&&i===N-1)?'red':(i%2?'gold':'dark');}
function wheelMarkup(){const c=wheelConf();const vals=c.prizes.length?c.prizes:WHEEL_DEMO;const N=vals.length;const seg=360/N;let maxC=-1;vals.forEach(v=>{const n=Number(v);if(isFinite(n)&&n>maxC)maxC=n;});
 const fills=[];for(let i=0;i<N;i++){const a0=i*seg,a1=a0+seg,am=a0+seg*0.45,k=wheelKind(i,N);if(k==='gold')fills.push(`#ffb84c ${a0}deg,#ffe1a0 ${am}deg,#d88a29 ${a1}deg`);else if(k==='red')fills.push(`#7a1d1d ${a0}deg,#b03a3a ${am}deg,#4a0f0f ${a1}deg`);else fills.push(`#15110c ${a0}deg,#332719 ${am}deg,#100e0a ${a1}deg`);}
 const line=Math.min(0.8,seg*0.03);const bg=`repeating-conic-gradient(from ${-seg/2}deg,transparent 0deg ${seg-line}deg,#a36c2e ${seg-line}deg ${seg}deg),conic-gradient(from ${-seg/2}deg,${fills.join(',')})`;
 const labels=vals.map((v,i)=>{const k=wheelKind(i,N);const col=k==='gold'?'#211207':'#fff0c8';const top=(maxC>0&&Number(v)===maxC)?' top':'';return `<span class="wheel-label${top}${N>8?' sm':''}" data-i="${i}" style="--a:${i*seg}deg;--c:${col}">${wheelLabel(v)}</span>`;}).join('');
 state.wheelRot=0;
 return `<div class="wheel-stage live"><div class="wheel-pointer" id="wheel-pointer"></div><div class="wheel live" id="wheel" data-n="${N}" style="background:${bg}">${labels}</div><div class="wheel-hub">${icon('crown')}</div></div>`;}
/* wheelSpinTo(idx, onDone): spins 5 full turns and stops with segment idx under the pointer (small random offset inside the segment). */
function wheelSpinTo(idx,onDone){const w=document.querySelector('#wheel');if(!w){if(onDone)onDone();return;}const N=Math.max(1,Number(w.dataset.n)||1),seg=360/N;const ptr=document.querySelector('#wheel-pointer');
 w.querySelectorAll('.wheel-label').forEach(l=>l.classList.remove('win','pass'));
 const j=(Math.random()*0.7-0.35)*seg;const want=((-(idx*seg+j))%360+360)%360;const base=state.wheelRot||0;const cur=((base%360)+360)%360;const d=((want-cur)%360+360)%360;const total=base+360*5+d;state.wheelRot=total;
 const dur=4400;w.style.transition=`transform ${dur}ms cubic-bezier(.12,.62,.08,1)`;
 requestAnimationFrame(()=>{w.style.transform=`rotate(${total}deg)`;});
 let last=-1,run=true;const tick=()=>{if(!run)return;const m=getComputedStyle(w).transform;let ang=0;if(m&&m!=='none'){const p=m.slice(m.indexOf('(')+1,-1).split(',').map(Number);ang=Math.atan2(p[1],p[0])*180/Math.PI;}const under=Math.round(((((-ang)%360)+360)%360)/seg)%N;if(under!==last){last=under;if(ptr){ptr.classList.remove('tick');void ptr.offsetWidth;ptr.classList.add('tick');}const l=w.querySelector('.wheel-label[data-i="'+under+'"]');if(l){l.classList.add('pass');setTimeout(()=>l.classList.remove('pass'),140);}}requestAnimationFrame(tick);};requestAnimationFrame(tick);
 setTimeout(()=>{run=false;if(ptr)ptr.classList.remove('tick');const l=w.querySelector('.wheel-label[data-i="'+idx+'"]');if(l)l.classList.add('win');if(onDone)onDone();},dur+80);}
async function wheelPlay(){if(state.busy)return;const pc=wheelConf();const start=document.querySelector('#game-start');if(!pc.live){previewPlay();return;}if(!pc.enabled){toast('LE888 Spin is not available right now.');return;}if(!pc.prizes.length){toast('LE888 Spin has no prizes set yet.');return;}state.busy=true;if(start)start.disabled=true;let res;try{res=await memberRequest('play',{game:'wheel',play_id:plinkoPlayId()});}catch(e){state.busy=false;if(start)start.disabled=false;toast(e&&e.message?e.message:'Could not play. Please try again.');return;}
 try{if(res&&typeof res.points==='number')memberData.member.points=res.points;if(res&&res.reward!==undefined)memberData.member.reward=res.reward;}catch(e){}
 const matches=[];pc.prizes.forEach((p,i)=>{if(p===String(res.win)||Number(p)===Number(res.win))matches.push(i);});const idx=matches.length?matches[Math.floor(Math.random()*matches.length)]:0;
 const cents=Number(res.win_cents)||Math.round(Number(res.win)*100)||0;let maxC=0;pc.prizes.forEach(p=>{const c=Math.round(Number(p)*100);if(c>maxC)maxC=c;});const tier=cents<=0?0:(cents>=maxC&&maxC>0?2:1);
 const stage=document.querySelector('.wheel-stage');
 wheelSpinTo(idx,function(){state.busy=false;if(start)start.disabled=false;if(cents>0){if(stage){const f=document.createElement('div');f.className='cross-flash'+(tier>=2?' big':'');stage.appendChild(f);setTimeout(()=>f.remove(),1000);crossConfetti(stage,tier>=2?70:30);plinkoWin(tier,stage);if(tier>=2)crossFireworks(stage);}toast('You won SGD '+plinkoLabel(res.win)+' reward credit!');}else toast('No prize this time. Spin again!');});}
function platformsPage(){return menuList([['games','Mini Games','games'],['rtp','RTP Info','rtp']])}

/* ===== LUCKY VAULT (egg): cost and prizes from Admin -> Games -> Lucky Vault. The SERVER picks the prize when a vault is tapped. ===== */
async function vaultPlay(tile){if(state.busy||!tile||tile.classList.contains('open'))return;const pc=gameConf('egg');if(!pc||!pc.enabled){toast('Lucky Vault is not available right now.');return;}if(!pc.prizes.length){toast('Lucky Vault has no prizes set yet.');return;}
 state.busy=true;document.querySelectorAll('.vault-tile').forEach(t=>t.classList.add('locked'));tile.classList.remove('locked');tile.classList.add('shake');
 let res;try{res=await memberRequest('play',{game:'egg',play_id:plinkoPlayId()});}catch(e){state.busy=false;document.querySelectorAll('.vault-tile').forEach(t=>t.classList.remove('locked','shake'));toast(e&&e.message?e.message:'Could not play. Please try again.');return;}
 try{if(res&&typeof res.points==='number')memberData.member.points=res.points;if(res&&res.reward!==undefined)memberData.member.reward=res.reward;}catch(e){}
 const cents=Number(res.win_cents)||Math.round(Number(res.win)*100)||0;let maxC=0;pc.prizes.forEach(p=>{const c=Math.round(Number(p)*100);if(c>maxC)maxC=c;});const tier=cents<=0?0:(cents>=maxC&&maxC>0?2:1);
 setTimeout(()=>{tile.classList.remove('shake');tile.classList.add('open',cents>0?'win':'empty');const lab=tile.querySelector('.vault-prize');if(lab){lab.querySelector('small').textContent=cents>0?'YOU WON':'EMPTY';lab.querySelector('b').textContent=cents>0?('SGD '+plinkoLabel(res.win)):'No prize';}
  document.querySelectorAll('.vault-tile').forEach(t=>{if(t!==tile)t.classList.add('dim');});
  const grid=document.querySelector('.vault-grid');if(cents>0&&grid){const f=document.createElement('div');f.className='cross-flash'+(tier>=2?' big':'');grid.appendChild(f);setTimeout(()=>f.remove(),1000);crossConfetti(grid,tier>=2?70:30);plinkoWin(tier,grid);if(tier>=2)crossFireworks(grid);}
  try{if(navigator.vibrate&&state.vibration!==false)navigator.vibrate(cents>0?[40,30,80]:30);}catch(e){}
  toast(cents>0?('You won SGD '+plinkoLabel(res.win)+' reward credit!'):'Empty vault this time. Try again!');
  setTimeout(()=>{document.querySelectorAll('.vault-tile').forEach(t=>t.classList.remove('open','win','empty','dim','locked'));state.busy=false;},2600);},900);}
function previewPlay(target){if(state.busy)return;state.busy=true;const start=document.querySelector('#game-start');if(start)start.disabled=true;const g=games[state.game];if(g.id==='wheel'){const w=document.querySelector('#wheel');wheelSpinTo(Math.floor(Math.random()*(Number(w&&w.dataset.n)||12)),null);}if(g.id==='plinko'){plinkoDrop(undefined,null,-1);}if(target&&g.id==='scratch'){flipReveal(target,['x2','x3','x5','x10','x20','x50'][Math.floor(Math.random()*6)],1,true);}if(target&&g.id==='egg')target.style.boxShadow='0 0 30px #ff8a1f';state.previewTimer=setTimeout(()=>{state.busy=false;toast('Preview complete · live outcomes require the backend.');if(start)start.disabled=false;},(g.id==='wheel'?4600:(g.id==='plinko'?5200:2100)))}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>b.dataset.go==='menu'?menu():go(b.dataset.go));document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>{state.game=games.findIndex(g=>g.id===b.dataset.game);go('game')});document.querySelectorAll('[data-deck]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.deck);i===state.game?go('game'):select(i)});document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>select(state.game+Number(b.dataset.step)));document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>select(Number(b.dataset.select)));const stage=document.querySelector('.deck-stage');if(stage){let x;stage.onpointerdown=e=>{x=e.clientX};stage.onpointerup=e=>{if(Math.abs(e.clientX-x)>35){select(state.game+(e.clientX<x?1:-1));stage.dataset.drag='1';setTimeout(()=>delete stage.dataset.drag,100)}};stage.addEventListener('click',e=>{if(stage.dataset.drag){e.preventDefault();e.stopPropagation()}},true);stage.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();select(state.game+(e.key==='ArrowRight'?1:-1))}};document.querySelector('#deck-play').onclick=()=>go('game')};document.querySelectorAll('[data-reward-tab]').forEach(b=>b.onclick=()=>{state.rewardTab=b.dataset.rewardTab;render()});document.querySelectorAll('[data-history-tab]').forEach(b=>b.onclick=()=>{state.historyTab=b.dataset.historyTab;render()});const claim=document.querySelector('#claim');if(claim)claim.onclick=()=>{state.claimed=true;render();toast('Check-in preview completed. No live reward was claimed.')};document.querySelectorAll('[data-amount]').forEach(b=>b.onclick=()=>document.querySelector('#amount').value=b.dataset.amount);const form=document.querySelector('#money-form');if(form)form.onsubmit=e=>{e.preventDefault();const amount=Number(document.querySelector('#amount').value);if(state.page==='withdraw'&&amount>28.5){toast('Amount exceeds the demo reward balance.');return}showModal('Review '+titles[state.page],`<p>Amount: SGD ${amount.toFixed(2)}<br>Method: ${document.querySelector('#method').value}</p><div class="notice">Preview only. No payment or withdrawal will be submitted.</div>`)};document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{state[b.dataset.toggle]=!state[b.dataset.toggle];render()});['account','password'].forEach(id=>{const f=document.querySelector('#'+id+'-form');if(f)f.onsubmit=e=>{e.preventDefault();toast('Preview only · changes have not been sent to your account.')}});const signout=document.querySelector('#signout');if(signout)signout.onclick=()=>showModal('Sign Out','<p>This is a local demo session. Your live account is unaffected.</p>');const copy=document.querySelector('#copy-invite');if(copy)copy.onclick=async()=>{try{await navigator.clipboard.writeText('LE888-PLAYER001');toast('Referral code copied.')}catch{toast('Your code: LE888-PLAYER001')}};const chatForm=document.querySelector('#chat-form');if(chatForm)chatForm.onsubmit=e=>{e.preventDefault();const input=chatForm.querySelector('input'),bubble=document.createElement('div');bubble.className='chat-message out';bubble.textContent=input.value;document.querySelector('#chat-messages').append(bubble);input.value='';toast('Demo message added locally. Not sent to support.')};document.querySelectorAll('[data-bet]').forEach(b=>b.onclick=()=>{if(state.busy)return;state.bet=Math.max(10,Math.min(500,state.bet+Number(b.dataset.bet)));render()});document.querySelectorAll('[data-stake]').forEach(b=>b.onclick=()=>{if(state.busy)return;state.bet=Number(b.dataset.stake);render()});const plinkoBoardEl=document.querySelector('.plinko-board');if(plinkoBoardEl)plinkoPegs(plinkoBoardEl);if(document.querySelector('#cross-board'))crossInit();else crossStopTraffic();if(document.querySelector('#crown-grid'))crownInit();const start=document.querySelector('#game-start');if(start)start.onclick=()=>{const g=games[state.game];if(g.id==='scratch'||g.id==='egg'){toast(g.id==='scratch'?'Tap any card to flip it.':'Tap a vault to open it.');if(g.id==='scratch')flipNudge();return}if(g.id==='plinko'&&plinkoConf()){plinkoPlay();return}if(g.id==='wheel'&&gameConf('wheel')){wheelPlay();return}previewPlay()};document.querySelectorAll('[data-flip],[data-vault]').forEach(b=>b.onclick=()=>{if(b.dataset.flip!==undefined&&gameConf('scratch')){flipPlay(b);return}if(b.dataset.vault!==undefined&&gameConf('egg')){vaultPlay(b);return}previewPlay(b)});const submit=document.querySelector('#submit-preview');if(submit)submit.onclick=()=>toast('Link a real game account through the original backend.')}
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1)||'home';if(p!==state.page){state.page=p;render()}});state.page=location.hash.slice(1)||'home';render();

/* ===== Fixed game screen: nothing scrolls. If the page is taller than the phone, shrink the board first, then zoom the page. ===== */
let fitTimer=null;
function scheduleFit(){clearTimeout(fitTimer);fitTimer=setTimeout(()=>{requestAnimationFrame(fitGame);},0);}
function fitGame(){const sc=document.querySelector('#screen');if(!sc||state.page!=='game'||!document.body.classList.contains('game-lock'))return;
 const vis=sc.querySelector('.cross-board,.plinko-board,.flip-grid,.wheel-stage,.crown-grid,.game-grid');
 sc.style.zoom='';if(vis){vis.style.maxWidth='';vis.style.marginLeft='';vis.style.marginRight='';vis.style.removeProperty('--ws');}
 sc.querySelectorAll('img').forEach(im=>{if(!im.complete&&!im.dataset.fitHook){im.dataset.fitHook='1';im.addEventListener('load',scheduleFit,{once:true});}});
 const title=sc.querySelector('.crown-title');if(title){title.style.width='';title.style.marginBottom='';}
 let over=sc.scrollHeight-sc.clientHeight;
 if(over>0&&title){title.style.width='58%';title.style.marginBottom='6px';over=sc.scrollHeight-sc.clientHeight;}
 if(over>0&&vis){const r=vis.getBoundingClientRect();const grid=/flip-grid|crown-grid|game-grid/.test(vis.className);
  if(vis.classList.contains('wheel-stage')){vis.style.setProperty('--ws',Math.max(220,r.height-over)+'px');}
  else{const h=Math.max(r.height*(grid?0.7:0.5),r.height-over);vis.style.maxWidth=(r.width*h/r.height)+'px';vis.style.marginLeft='auto';vis.style.marginRight='auto';}
  over=sc.scrollHeight-sc.clientHeight;}
 if(over>2){sc.style.zoom=String(Math.max(0.55,sc.clientHeight/sc.scrollHeight));}
 const pb=sc.querySelector('.plinko-board');if(pb&&!state.busy)plinkoPegs(pb);}
window.addEventListener('resize',()=>{if(state.page==='game')scheduleFit();});
window.addEventListener('orientationchange',()=>{if(state.page==='game')setTimeout(scheduleFit,250);});

